fn htmlParseHTMLAttribute(
    mut ctxt: htmlParserCtxtPtr,
    stop: xmlChar,
) -> *mut xmlChar {
    unsafe {
        let mut buffer_size: c_int = HTML_PARSER_BUFFER_SIZE;
        let mut buffer =
            xmlMallocAtomic.expect("non-null function pointer")(buffer_size as size_t)
                as *mut xmlChar;
        if buffer.is_null() {
            htmlErrMemory(
                ctxt as xmlParserCtxtPtr,
                b"buffer allocation failed\n\0" as *const u8 as *const c_char,
            );
            return ::core::ptr::null_mut::<xmlChar>();
        }

        let mut out = buffer;
        let maxLength: c_int = if (*ctxt).options & XML_PARSE_HUGE as c_int != 0 {
            XML_MAX_HUGE_LENGTH
        } else {
            XML_MAX_TEXT_LENGTH
        };

        #[inline(always)]
        unsafe fn grow_buffer(
            ctxt: htmlParserCtxtPtr,
            buffer: &mut *mut xmlChar,
            out: &mut *mut xmlChar,
            buffer_size: &mut c_int,
        ) -> bool {
            if (*out).offset_from(*buffer) as c_long <= (*buffer_size - 100) as c_long {
                return true;
            }
            let indx = (*out).offset_from(*buffer) as c_int;
            *buffer_size *= 2;
            let tmp = xmlRealloc.expect("non-null function pointer")(
                *buffer as *mut c_void,
                *buffer_size as size_t,
            ) as *mut xmlChar;
            if tmp.is_null() {
                htmlErrMemory(
                    ctxt as xmlParserCtxtPtr,
                    b"growing buffer\n\0" as *const u8 as *const c_char,
                );
                xmlFree.expect("non-null function pointer")(*buffer as *mut c_void);
                return false;
            }
            *buffer = tmp;
            // SAFETY: indx was computed from out-buffer before realloc and remains a valid in-bounds offset in the resized allocation.
            *out = unsafe { tmp.offset(indx as isize) };
            true
        }

        #[inline(always)]
        unsafe fn push_utf8(out: &mut *mut xmlChar, c: c_uint) {
            if c < 0x80 {
                // SAFETY: caller guarantees sufficient writable space in the output buffer.
                unsafe {
                    **out = c as xmlChar;
                    *out = (*out).offset(1);
                }
            } else if c < 0x800 {
                // SAFETY: caller guarantees sufficient writable space in the output buffer.
                unsafe {
                    **out = ((c >> 6) & 0x1f | 0xc0) as xmlChar;
                    *out = (*out).offset(1);
                    **out = ((c & 0x3f) | 0x80) as xmlChar;
                    *out = (*out).offset(1);
                }
            } else if c < 0x10000 {
                // SAFETY: caller guarantees sufficient writable space in the output buffer.
                unsafe {
                    **out = ((c >> 12) & 0xf | 0xe0) as xmlChar;
                    *out = (*out).offset(1);
                    **out = (((c >> 6) & 0x3f) | 0x80) as xmlChar;
                    *out = (*out).offset(1);
                    **out = ((c & 0x3f) | 0x80) as xmlChar;
                    *out = (*out).offset(1);
                }
            } else {
                // SAFETY: caller guarantees sufficient writable space in the output buffer.
                unsafe {
                    **out = ((c >> 18) & 0x7 | 0xf0) as xmlChar;
                    *out = (*out).offset(1);
                    **out = (((c >> 12) & 0x3f) | 0x80) as xmlChar;
                    *out = (*out).offset(1);
                    **out = (((c >> 6) & 0x3f) | 0x80) as xmlChar;
                    *out = (*out).offset(1);
                    **out = ((c & 0x3f) | 0x80) as xmlChar;
                    *out = (*out).offset(1);
                }
            }
        }

        loop {
            let input = (*ctxt).input;
            let curp = (*input).cur;
            let curc = *curp as c_int;

            if curc == 0 || curc == stop as c_int {
                break;
            }
            if stop as c_int == 0 {
                if curc == '>' as i32 {
                    break;
                }
                if curc == 0x20
                    || (0x9 <= curc && curc <= 0xa)
                    || curc == 0xd
                {
                    break;
                }
            }

            if curc == '&' as i32 {
                let nextc = *curp.offset(1) as c_int;
                if nextc == '#' as i32 {
                    let c = htmlParseCharRef(ctxt) as c_uint;
                    push_utf8(&mut out, c);
                    if !grow_buffer(ctxt, &mut buffer, &mut out, &mut buffer_size) {
                        return ::core::ptr::null_mut::<xmlChar>();
                    }
                } else {
                    let mut name: *const xmlChar = ::core::ptr::null();
                    let ent = htmlParseEntityRef(ctxt, &raw mut name);
                    if name.is_null() {
                        *out = '&' as i32 as xmlChar;
                        // SAFETY: out points into a valid writable buffer and advances by one byte.
                        out = unsafe { out.offset(1) };
                        if !grow_buffer(ctxt, &mut buffer, &mut out, &mut buffer_size) {
                            return ::core::ptr::null_mut::<xmlChar>();
                        }
                    } else if ent.is_null() {
                        *out = '&' as i32 as xmlChar;
                        // SAFETY: out points into a valid writable buffer and advances by one byte.
                        out = unsafe { out.offset(1) };
                        let mut cur = name;
                        while *cur as c_int != 0 {
                            if !grow_buffer(ctxt, &mut buffer, &mut out, &mut buffer_size) {
                                return ::core::ptr::null_mut::<xmlChar>();
                            }
                            *out = *cur;
                            // SAFETY: cur walks a valid NUL-terminated entity name string one byte at a time.
                            cur = unsafe { cur.offset(1) };
                            // SAFETY: out points into a valid writable buffer and advances by one byte.
                            out = unsafe { out.offset(1) };
                        }
                    } else {
                        if !grow_buffer(ctxt, &mut buffer, &mut out, &mut buffer_size) {
                            return ::core::ptr::null_mut::<xmlChar>();
                        }
                        push_utf8(&mut out, (*ent).value);
                    }
                }
            } else {
                if !grow_buffer(ctxt, &mut buffer, &mut out, &mut buffer_size) {
                    return ::core::ptr::null_mut::<xmlChar>();
                }
                let mut l: c_int = 0;
                let c = htmlCurrentChar(ctxt as xmlParserCtxtPtr, &raw mut l) as c_uint;
                if (*ctxt).instate as c_int == XML_PARSER_EOF as c_int {
                    xmlFree.expect("non-null function pointer")(buffer as *mut c_void);
                    return ::core::ptr::null_mut::<xmlChar>();
                }
                push_utf8(&mut out, c);
                if *(*(*ctxt).input).cur as c_int == '\n' as i32 {
                    (*(*ctxt).input).line += 1;
                    (*(*ctxt).input).col = 1;
                } else {
                    (*(*ctxt).input).col += 1;
                }
                (*ctxt).token = 0;
                // SAFETY: l is the byte width returned by htmlCurrentChar for the current cursor position.
                (*(*ctxt).input).cur = unsafe { (*(*ctxt).input).cur.offset(l as isize) };
            }

            if out.offset_from(buffer) as c_long > maxLength as c_long {
                htmlParseErr(
                    ctxt as xmlParserCtxtPtr,
                    XML_ERR_ATTRIBUTE_NOT_FINISHED,
                    b"attribute value too long\n\0" as *const u8 as *const c_char,
                    ::core::ptr::null::<xmlChar>(),
                    ::core::ptr::null::<xmlChar>(),
                );
                xmlFree.expect("non-null function pointer")(buffer as *mut c_void);
                return ::core::ptr::null_mut::<xmlChar>();
            }
        }

        *out = 0 as xmlChar;
        buffer
    }
}

